import java.util.*;
public class B{
	public static void main(String args[]){
		Scanner scan = new Scanner(System.in);
		char c;

		boolean bracket = false, brackword = false;
		int prevWord = 0, inBrackets = 0, word = 0;

		int n = scan.nextInt();
		scan.nextLine();
		String in = scan.nextLine();
		for(int i = 0; i < n; i++){

			c = in.charAt(i);

			if(c =='('){
				if(word > prevWord)
					prevWord = word;
				word = 0;
				bracket = true;
			}
			else if(c == ')'){
				bracket = false;
				if(brackword)
					inBrackets++;
				brackword = false;
			}
			else if(c == '_'){
				if(word > prevWord)
					prevWord = word;
				word = 0;
				if(brackword){
					inBrackets++;
					brackword = false;
				}

			}
			else{
				if(bracket)
					brackword = true;
				else
					word++;
			}
		}

		if(word > prevWord)
			prevWord = word;


		System.out.println(prevWord + " " + inBrackets);
	}
}

